select tabid into @tabid from LD_tab where name='SalesOrder';
select sequence into @seq from ld_field where tabid=@tabid and columnname='sostatus';
update ld_field set sequence=@seq+1 where sequence>=@seq and block=61;
select id into @id from ld_field_seq;
update ld_field_seq set id=@id+1 where not exists(select 1 from ld_field where tabid=@tabid and columnname='parentid');
insert into ld_field (tabid,fieldid,columnname,tablename,generatedtype,uitype,fieldname,fieldlabel,readonly,presence,defaultvalue,maximumlength,sequence,block,displaytype,typeofdata,quickcreate,quickcreatesequence,info_type,masseditable,helpinfo,fieldonly)
select @tabid,@id+1,'parentid','LD_salesorder',1,80,'salesorder_id','上级合同',1,2,'',100,@seq,61,1,'I~O',3,NULL,'BAS',1,NULL,0  
from dual where  not exists (select 1 from  ld_field where tabid=@tabid and columnname='parentid') ;
delimiter;

call addcolumn('LD_salesorder','parentid','int','19',0);
call fieldprofile('SalesOrder');
call getallprofile('SalesOrder');
delimiter;

-- add by can
update ld_visibility set visibility='私有'  where visibility='private';
update ld_visibility set visibility='公共'  where visibility='public';
CREATE TABLE if not EXISTS `ld_desk` (
  `deskid` int(11) NOT NULL auto_increment,
  `languagetype` varchar(20) default NULL,
  `labelbol` varchar(60) default NULL,
  `Fieldlabel` varchar(250) default NULL,
  `Labeltype` varchar(20) default NULL,
  PRIMARY KEY  (`deskid`),
  KEY `idx_languatetype_desk` USING BTREE (`languagetype`,`Labeltype`)
) ENGINE=InnoDB AUTO_INCREMENT=4935 DEFAULT CHARSET=utf8;

CREATE TABLE if not exists `ld_tranlabel` (
  `Tranlabelid` int(11) NOT NULL auto_increment,
  `languagetype` varchar(20) default NULL,
  `trantable` varchar(20) default NULL,
  `tabid` int(19) default NULL,
  `Relateid` int(19) default NULL,
  `fieldlabel` varchar(100) default NULL,
  PRIMARY KEY  (`Tranlabelid`),
  KEY `idx_trantable_tranlabel` USING BTREE (`languagetype`,`trantable`,`tabid`)
) ENGINE=InnoDB AUTO_INCREMENT=4308 DEFAULT CHARSET=utf8;
delimiter;


