-- add 2014-03-17 至 2014-03-25
update ld_tab set printtab=1 where tabid=47;
update ld_field set fieldlabel='参考成本' where tabid=14 and columnname='costprice';
delimiter;

call addcolumn('ld_inventoryproductrel','productcost','decimal','18',null);
delimiter;

ALTER TABLE ld_inventoryproductrel MODIFY productcost decimal(18,2) not null  default '0';
delimiter;

call fieldprofile('VendorContactRecords');
call getallprofile('VendorContactRecords');
delimiter;

update  ld_field set  defaultvalue='thistoday' where columnname='duedate' 
and tabid in (SELECT tabid  from  ld_tab  where  name='PurchaseOrder');
update  ld_field set  defaultvalue='thistoday' where columnname='start_date' 
and tabid in (SELECT tabid  from  ld_tab  where  name='ServiceContracts');
delimiter;
update ld_tab set printtab = 1 where name in ('Project','ProjectTask');
delimiter;

CREATE TABLE IF NOT EXISTS `LD_specialcircumstances` (
  `id` int(11) NOT NULL auto_increment,
  `special_value` varchar(25) default NULL,
  `special_type` varchar(25) default NULL,
  `description` varchar(500) default NULL,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8 AUTO_INCREMENT=0 ;
delimiter;

insert into LD_specialcircumstances(special_value,special_type,description) 
select '0','1','菜单栏中，应收款统计表链接是否显示。1为显示，0为不显示'
from dual where not EXISTS(select 1 from LD_specialcircumstances  where special_type='1');
delimiter;

call addcolumn('LD_potential','related_accountid','int','11',null);
call addcolumn('LD_potential','related_contactid','int','11',null);
delimiter;

