CREATE TABLE IF NOT EXISTS `LD_salestarget` (
  `id` int(11) NOT NULL auto_increment,
  `userid` int(11) default '0',
  `targetyear` int(11) default '0',
	`targetmouth` int(11) default '0',
	`paymentamount` decimal(25,2) default '0',
	`contractamount` decimal(25,2) default '0',
  `accountsnumber` int(11) default '0',
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8 AUTO_INCREMENT=0 ;
delimiter;

select max(tabid) into @tabid from ld_tab;
select tabsequence into @tabsequence from ld_tab where `name` = 'Cache';
insert into LD_tab(tabid,`name`,presence,tabsequence,tablabel,customized,isentitytype)
select @tabid+1,'SalesGoal',0,@tabsequence,'SalesGoal',0,0 from dual where not exists
(select * from LD_tab where `name` = 'SalesGoal');

select tabid into @tabid from ld_tab where `name` = 'SalesGoal';
insert into ld_languagepackage(tabid,tablabel,chinesename,newchinesename)
select @tabid,'SalesGoal','销售目标','销售目标' from dual where not exists 
(select * from ld_languagepackage where `tablabel` = 'SalesGoal');

select tabid into @tabid from ld_tab where `name` = 'SalesGoal';
select parenttabid into @parenttabid from ld_parenttab where parenttab_label = 'Tools';
select sequence into @sequence from ld_parenttabrel where parenttabid = @parenttabid and tabid = (select tabid from ld_tab where `name` = 'Cache');
insert into ld_parenttabrel(parenttabid,tabid,sequence)
select @parenttabid,@tabid,@sequence from dual where not exists 
(select * from ld_parenttabrel where parenttabid = @parenttabid and tabid = @tabid);
delimiter;

update ld_tab set presence = 1 where `name` = 'SalesGoal' and exists (select * from ld_version where versiontype = 2);
