insert into  ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel) 
select 'en','LD_field',@tabid,@relateid,'state' from dual 
where not EXISTS(select 1 from ld_tranlabel where languagetype='en' and trantable='LD_field' and relateid=@relateid);

