  `bankname` varchar(100) default NULL,
  `InitMoney` decimal(18,2) default NULL,
  `curbalancemoney` decimal(18,2) default '0.00',
  `confirmed` int(1) default '0',
  `currency_id` int(1) default '1',
  `conversion_rate` int(1) default '1',
  `confirmtime` datetime default NULL,
  `confirmby` int(19) default NULL,
  PRIMARY KEY  (`Bankaccountsetid`),
  KEY `Bankaccountsetid_bankaccountset_id` USING BTREE (`Bankaccountsetid`),
  CONSTRAINT `fk_1_lingdang_Bankaccountsetid` FOREIGN KEY (`Bankaccountsetid`) REFERENCES `ld_crmentity` (`crmid`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=COMPACT;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_bankaccountsetcf` (
  `Bankaccountsetid` int(19) default NULL,
  KEY `fk_1_lingdang_bankaccountsetcf` USING BTREE (`Bankaccountsetid`),
  CONSTRAINT `fk_1_lingdang_bankaccountsetcf` FOREIGN KEY (`Bankaccountsetid`) REFERENCES `ld_bankaccountset` (`Bankaccountsetid`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

