delete from ld_customview where viewname='All' and entitytype='CashBill';
delimiter;

select max(cvid) into @maxid from ld_customview; 
insert into LD_customview (cvid,viewname,setdefault,setmetrics,entitytype,status,userid,sequence)
select  @maxid+1,'All',1,0, 'CashBill',3,1,1 from dual 
where not exists(select 1 from LD_customview where viewname='All' and entitytype='CashBill');
update ld_customview_seq set id = (select max(cvid) from ld_customview);
delimiter;
   
