DROP PROCEDURE IF EXISTS changeColumnTittle; 
DELIMITER || 

CREATE PROCEDURE changeColumnTittle() 
BEGIN 
select database() into @tableschema;
SELECT count(1) INTO @colName 
FROM information_schema.columns
WHERE TABLE_NAME = 'ld_troubletickets'
AND COLUMN_NAME = 'title' 
AND TABLE_SCHEMA=@tableschema;

IF @colName>0 THEN 
   ALTER TABLE LD_troubletickets change title ticket_title varchar(200);
END IF;
end || 
delimiter;

