CREATE TABLE IF NOT EXISTS `ld_automaticreminds` (
  `id` int(11) NOT NULL auto_increment,
  `tabid` int(11) NOT NULL,
  `name` varchar(200) NOT NULL,
  `columnname` varchar(200) default NULL,
  `startdate` datetime default NULL,
  `remindnum` int(11) default NULL,
  `remindway` int(11) default NULL,
  `remindday` int(11) default NULL,
  `reminder` int(11) default NULL,
  `remindcontent` text,
  `status` int(11) default NULL,
  `smcreatorid` int(11) default NULL,
  `modifiedby` int(11) default NULL,
  `createdtime` datetime default NULL,
  `modifiedtime` datetime default NULL,
  PRIMARY KEY  (`id`),
  KEY `idx_autoreminds_reamindway` USING BTREE (`status`,`remindway`)
) ENGINE=InnoDB AUTO_INCREMENT=125 DEFAULT CHARSET=utf8;
delimiter;
CREATE TABLE IF NOT EXISTS `ld_remindway` (
  `wayid` int(11) NOT NULL,
  `remindsday` int(11) default NULL,
  `sequence` int(11) default NULL,
  KEY `idx_remindsway_wayid` USING BTREE (`wayid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;
CREATE TABLE IF NOT EXISTS `ld_remindcvadvfilter` (
  `cvid` int(11) NOT NULL,
  `columnindex` int(11) default NULL,
  `columnname` varchar(200) default NULL,
  `comparator` varchar(10) default NULL,
  `value` varchar(100) default NULL,
  `groupid` int(11) default NULL,
  `column_condition` varchar(10) default NULL,
  KEY `idx_remindcvadvfilter_cvid` USING BTREE (`cvid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;
CREATE TABLE IF NOT EXISTS `ld_remindcvadvfilter_grouping` (
  `groupid` int(11) NOT NULL,
  `cvid` int(11) NOT NULL,
  `group_condition` varchar(255) default NULL,
  `condition_expression` text,
  PRIMARY KEY  (`groupid`,`cvid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;
CREATE TABLE IF NOT EXISTS `ld_remindcvstdfilter` (
  `cvid` int(11) NOT NULL,
  `columnname` varchar(200) default NULL,
  `stdfilter` varchar(100) default NULL,
  `startdate` date default NULL,
  `enddate` date default NULL,
  KEY `idx_remindscvstdfiler_cvid` USING BTREE (`cvid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;
CREATE TABLE IF NOT EXISTS `ld_tmpreminder` (
  `reminds_ruleid` int(19) default NULL,
  `content` varchar(1000) default NULL,
  `reminderid` int(11) default NULL,
  `remindtime` datetime default NULL,
  `related_to` int(19) default NULL,
  `reltab` varchar(50) default NULL,
  `remindnum` int(7) default NULL,
  `id` int(19) NOT NULL auto_increment,
  PRIMARY KEY  (`id`),
  KEY `idx_ruleid_num_tmpreminder` USING BTREE (`reminds_ruleid`,`remindnum`),
  KEY `idx_reminderid_tmpremind` USING BTREE (`reminderid`,`remindtime`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8;
delimiter;
call addcolumn('LD_reminds','reminds_ruleid','int','19',0);
call addtableIndex('ld_reminds','reminds_ruleid','reminds_ruleid');
delimiter;

